"""A property test: withdraw gives the balance minus the amount for each pair in range."""

import unittest

from wallet.core import withdraw


class BalanceProperty(unittest.TestCase):
    def test_withdraw_subtracts(self) -> None:
        for balance in range(0, 60, 7):
            for amount in range(0, balance + 1, 3):
                self.assertEqual(withdraw(balance, amount), balance - amount)


if __name__ == "__main__":
    unittest.main()
